(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const save = (key, value) => localStorage.setItem(key, JSON.stringify(value));
  const load = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
  const state = { buxns: load('playroom-buxns', 120), selectedBlock: 'grass', blocks: load('playroom-blocks', []), worlds: load('playroom-worlds', []), owned: load('playroom-owned', ['Sunny cap','Cloud tee']), equipped: load('playroom-equipped', {hat:'Sunny cap',top:'Cloud tee',face:'Happy',trail:'None'}), quest: load('playroom-quest', 0), game: null, keys: new Set(), camera: 0, buildScale: 1, wardrobePage: 0, wardrobeCategory: 'all', toastTimer: 0 };
  const canvas = $('#gameCanvas'); const ctx = canvas.getContext('2d');
  const blockColors = {grass:['#91dfa1','#67ca86','#4eae72'],neon:['#8ce9ff','#52bee8','#3896c7'],bounce:['#f5a1c2','#df75a9','#bd568d'],lava:['#ffc374','#fa805e','#dc5c4d']};
  const names = {grass:'Grass',neon:'Neon',bounce:'Bouncy',lava:'Hot'};
  const itemCatalog = [
    {name:'Sunny cap',cat:'hat',icon:'☀',price:0,color:'#ffe398',rarity:'STARTER'}, {name:'Cloud tee',cat:'top',icon:'▰',price:0,color:'#a8e7e0',rarity:'STARTER'}, {name:'Starry beret',cat:'hat',icon:'✦',price:35,color:'#b7aaff'}, {name:'Mint hoodie',cat:'top',icon:'▰',price:50,color:'#8ee0c6'}, {name:'Happy',cat:'face',icon:'☺',price:0,color:'#ffd4af',rarity:'STARTER'}, {name:'Pixel shades',cat:'face',icon:'▣',price:28,color:'#b1d8f6'}, {name:'Comet trail',cat:'trail',icon:'✧',price:70,color:'#f9a5c1'}, {name:'Moon boots',cat:'top',icon:'◢',price:45,color:'#c4b8ff'}, {name:'Flower crown',cat:'hat',icon:'❀',price:65,color:'#ffb6c8'}, {name:'Bubble trail',cat:'trail',icon:'○',price:55,color:'#9ddff6'}, {name:'Golden grin',cat:'face',icon:'✺',price:95,color:'#ffd16e'}, {name:'Cloud wings',cat:'top',icon:'⌁',price:120,color:'#d5d9ff'}, {name:'Tiny frog',cat:'hat',icon:'🐸',price:80,color:'#a9e3a8'}, {name:'Rainbow trail',cat:'trail',icon:'〰',price:150,color:'#f4a8d7'}, {name:'Cozy sweater',cat:'top',icon:'▤',price:38,color:'#f4bd91'}, {name:'Star freckles',cat:'face',icon:'✦',price:25,color:'#ffc7b1'}, {name:'Daisy cap',cat:'hat',icon:'❁',price:42,color:'#ffdf9a'}, {name:'Twinkle trail',cat:'trail',icon:'✦',price:90,color:'#cbb6ff'}, {name:'Ocean jacket',cat:'top',icon:'▰',price:62,color:'#80c9e8'}, {name:'Sleepy eyes',cat:'face',icon:'☾',price:32,color:'#d6c9f3'}, {name:'Party hat',cat:'hat',icon:'♟',price:20,color:'#f89db3'}, {name:'Soft glow',cat:'trail',icon:'◌',price:110,color:'#f4da82'}, {name:'Berry vest',cat:'top',icon:'▰',price:46,color:'#ed9eb2'}, {name:'Button nose',cat:'face',icon:'●',price:18,color:'#ffc8af'}
  ];
  const communitySeeds = [
    {name:'Moonlight Market',creator:'lilacdreams',icon:'☾',tag:'SOCIAL',desc:'A tiny night market full of surprises',players:'2,043',rating:'4.9',colors:['#8f79d2','#344c83']},
    {name:'Jellybean Jungle',creator:'pixelpoppy',icon:'❋',tag:'ADVENTURE',desc:'Bounce through the candy-colored canopy',players:'1,821',rating:'4.8',colors:['#7bd9b9','#43a4aa']},
    {name:'Tiny Town',creator:'mossyboots',icon:'⌂',tag:'ROLEPLAY',desc:'Build a home and meet the neighbors',players:'1,204',rating:'4.9',colors:['#ffc981','#eb968b']},
    {name:'Starfall Obby',creator:'orbital.ollie',icon:'✦',tag:'OBBY',desc:'Can you make it across the galaxy?',players:'988',rating:'4.7',colors:['#566dc8','#252852']},
    {name:'Sleepy Sea',creator:'bluehour',icon:'≈',tag:'CHILL',desc:'Collect shells and drift with the tide',players:'756',rating:'4.8',colors:['#83d6e5','#5f8dc6']},
    {name:'Puddle Park',creator:'fernfriend',icon:'☂',tag:'HANGOUT',desc:'Rainy day vibes, sunny day friends',players:'532',rating:'4.6',colors:['#98d4b8','#66a5aa']}
  ];
  const resizeCanvas = () => { const r=canvas.getBoundingClientRect(); if(!r.width||!r.height)return; const d=Math.min(devicePixelRatio||1,2); canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);drawBuilder(); };
  const poly = (points, color, stroke) => {ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}};
  function drawIsoBlock(x,y,w,h,colors,scale=1){ const d=13*scale; poly([[x,y],[x+w,y],[x+w+d,y+d],[x+d,y+d]],colors[0]);poly([[x,y],[x+d,y+d],[x+d,y+d+h],[x,y+h]],colors[1]);poly([[x+d,y+d],[x+w+d,y+d],[x+w+d,y+d+h],[x+d,y+d+h]],colors[2]); }
  function drawBuilder(){if(!canvas.width)return;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#d7eff8');sky.addColorStop(.68,'#eaf5f7');sky.addColorStop(1,'#b3d9d3');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle='#ffdc91';ctx.beginPath();ctx.arc(w*.79,h*.24,Math.min(w,h)*.07,0,Math.PI*2);ctx.fill();
    // distant floating islands
    for(let i=0;i<5;i++){const x=w*(.1+i*.2),y=h*(.25+(i%2)*.08);ctx.fillStyle=i%2?'#b4d7e4':'#c6e7dc';ctx.beginPath();ctx.ellipse(x,y,31,9,0,0,7);ctx.fill();ctx.fillStyle='#9dc4d3';ctx.beginPath();ctx.moveTo(x-16,y+3);ctx.lineTo(x+17,y+3);ctx.lineTo(x+5,y+21);ctx.closePath();ctx.fill();}
    const scale=Math.min(w/560,h/390)*state.buildScale,cw=46*scale,ch=23*scale,depth=16*scale,ox=w/2-4*scale,oy=h*.39;for(let row=0;row<8;row++)for(let col=0;col<8;col++){const x=ox+(col-row)*cw/2,y=oy+(col+row)*ch/2;if(row===7){drawIsoBlock(x,y,cw*.97,depth, ['#8fe1a0','#67ca86','#4eae72'],scale);continue;}ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+cw/2,y+ch/2);ctx.lineTo(x,y+ch);ctx.lineTo(x-cw/2,y+ch/2);ctx.closePath();ctx.fillStyle=(row+col)%2?'#ffffff30':'#ffffff53';ctx.fill();ctx.strokeStyle='#ffffff88';ctx.lineWidth=1;ctx.stroke();}
    // spawn / goal tiles
    const tile=(col,row,top,side)=>{const x=ox+(col-row)*cw/2,y=oy+(col+row)*ch/2;poly([[x,y],[x+cw/2,y+ch/2],[x,y+ch],[x-cw/2,y+ch/2]],top);poly([[x-cw/2,y+ch/2],[x,y+ch],[x,y+ch+depth],[x-cw/2,y+ch/2+depth]],side);};tile(0,0,'#80c9f4','#58a5d9');tile(7,0,'#73dba9','#47b981');
    state.blocks.forEach(b=>{const x=ox+(b.col-b.row)*cw/2,y=oy+(b.col+b.row)*ch/2;const pal=blockColors[b.type]||blockColors.grass;drawIsoBlock(x,y,cw*.95,depth,pal,scale);});
    // avatar near spawn
    const ax=ox,ay=oy+ch*.45-16*scale;ctx.fillStyle='#6b5cda';ctx.beginPath();ctx.roundRect(ax-6*scale,ay,12*scale,15*scale,4*scale);ctx.fill();ctx.fillStyle='#ffd2ae';ctx.beginPath();ctx.arc(ax,ay-5*scale,6*scale,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff91a9';ctx.fillRect(ax-5*scale,ay-13*scale,10*scale,4*scale);
    // soft haze
    const fog=ctx.createLinearGradient(0,h*.75,0,h);fog.addColorStop(0,'#ffffff00');fog.addColorStop(1,'#eaf6f2bb');ctx.fillStyle=fog;ctx.fillRect(0,h*.72,w,h*.28);
  }
  function addBlockAt(clientX,clientY){const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,scale=Math.min(w/560,h/390)*state.buildScale,cw=46*scale,ch=23*scale,ox=w/2-4*scale,oy=h*.39;const px=clientX-r.left,py=clientY-r.top;let best=null,dist=Infinity;for(let row=0;row<7;row++)for(let col=0;col<8;col++){const x=ox+(col-row)*cw/2,y=oy+(col+row)*ch/2,dx=px-x,dy=py-(y+ch/2),d=(dx*dx)/(cw*cw)+(dy*dy)/(ch*ch);if(d<dist){dist=d;best={col,row};}}if(dist>.9||!best)return;const ix=state.blocks.findIndex(b=>b.col===best.col&&b.row===best.row);if(ix>=0)state.blocks.splice(ix,1);else state.blocks.push({...best,type:state.selectedBlock});save('playroom-blocks',state.blocks);$('#blockCount').textContent=state.blocks.length;drawBuilder();}
  canvas.addEventListener('pointerdown',e=>{if($('#view-builder').classList.contains('active'))addBlockAt(e.clientX,e.clientY);else if(state.game)handleTap(e.clientX,e.clientY);});window.addEventListener('resize',resizeCanvas);
  function showView(name){if(state.game){stopGame();} $$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='builder')requestAnimationFrame(resizeCanvas);if(name==='community')renderCommunity();if(name==='avatar')renderWardrobe();window.scrollTo({top:0,behavior:'smooth'});}
  $$('[data-view]').forEach(el=>el.addEventListener('click',()=>showView(el.dataset.view)));
  $$('.nav-item[data-game],.mini-nav[data-game],.primary-btn[data-game],.game-card[data-game],.join-btn[data-game]').forEach(el=>el.addEventListener('click',()=>startGame(el.dataset.game)));
  $$('.tool-choice,.builder-mobile-tools button').forEach(el=>el.addEventListener('click',()=>{state.selectedBlock=el.dataset.block;$$('[data-block]').forEach(x=>x.classList.toggle('selected',x.dataset.block===state.selectedBlock));}));
  $('#blockCount').textContent=state.blocks.length;
  $('#clearBuildBtn').addEventListener('click',()=>{state.blocks=[];save('playroom-blocks',state.blocks);$('#blockCount').textContent='0';drawBuilder();});
  $('#builderZoom').addEventListener('click',()=>{state.buildScale=state.buildScale>=1.2?.8:state.buildScale+.2;$('#builderZoom').textContent=`−　${Math.round(state.buildScale*100)}%　＋`;drawBuilder();});
  $('#testBuildBtn').addEventListener('click',()=>startGame('custom'));
  $('#publishBtn').addEventListener('click',()=>openModal(`<div class="modal-emoji">✳</div><span class="eyebrow">SHARE YOUR CREATION</span><h2>Give your world a name</h2><p>Your world is saved to this device and added to your Worlds page.</p><input class="modal-input" id="worldNameInput" maxlength="28" placeholder="e.g. Rainbow Rooftops"><button class="primary-btn" id="confirmPublish">Publish world <span>↗</span></button>`));
  document.addEventListener('click',e=>{if(e.target.id==='confirmPublish'){const name=$('#worldNameInput').value.trim()||'My little world';state.worlds.unshift({name,creator:'you',icon:'✳',tag:'PLAYER MADE',desc:`A world made by you · ${state.blocks.length} blocks`,players:'1',rating:'new',colors:['#81d8bb','#6961c5'],blocks:state.blocks});save('playroom-worlds',state.worlds);$('#worldCount').textContent=String(8+state.worlds.length).padStart(2,'0');closeModal();openModal(`<div class="modal-emoji">✦</div><h2>Your world is out there!</h2><p><b>${escapeHTML(name)}</b> was added to the community worlds on this device.</p><div class="modal-success">✳ Published locally · ${state.blocks.length} blocks</div><button class="primary-btn" id="goWorlds">Explore worlds <span>→</span></button>`);}if(e.target.id==='goWorlds'){closeModal();showView('community');}});
  $('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});
  function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('active');}function closeModal(){$('#modalBackdrop').classList.remove('active');}
  function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function renderCommunity(){const all=[...state.worlds,...communitySeeds];$('#communityGrid').innerHTML=all.map((w,i)=>`<article class="world-card" data-world="${i}"><div class="world-art" style="background:linear-gradient(145deg,${w.colors[0]},${w.colors[1]})"><small>${w.tag}</small><span>${w.icon}</span></div><div class="world-copy"><div>by ${escapeHTML(w.creator)} <span class="rating">★ ${w.rating}</span></div><h3>${escapeHTML(w.name)}</h3><p>${escapeHTML(w.desc)}</p></div></article>`).join('');$$('.world-card').forEach(card=>card.addEventListener('click',()=>startGame('community')));}
  $$('.filter-chip').forEach(btn=>btn.addEventListener('click',()=>{$$('.filter-chip').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');}));
  $('#worldSort').addEventListener('change',()=>{if($('#worldSort').value==='Newest first')state.worlds.reverse();renderCommunity();});
  function renderWardrobe(){const filtered=itemCatalog.filter(i=>state.wardrobeCategory==='all'||i.cat===state.wardrobeCategory);const start=state.wardrobePage*12,items=filtered.slice(start,start+12);$('#wardrobeGrid').innerHTML=items.map(i=>{const owned=state.owned.includes(i.name);return `<article class="item-card ${owned?'owned':''}" data-item="${escapeHTML(i.name)}" data-cat="${i.cat}"><div class="item-art" style="background:${i.color}">${i.icon}</div><b>${escapeHTML(i.name)}</b><span class="item-price">${owned?'OWNED':i.price===0?'FREE':`✦ ${i.price}`}</span></article>`;}).join('');$('#wardrobePageLabel').textContent=`Showing ${filtered.length?start+1:0}–${Math.min(start+12,filtered.length)} of ${filtered.length} items`;$$('.item-card').forEach(card=>card.addEventListener('click',()=>buyItem(card.dataset.item)));}
  function buyItem(name){const item=itemCatalog.find(i=>i.name===name);if(!item)return;if(state.owned.includes(name)){equipItem(item);return;}if(state.buxns<item.price){openModal(`<div class="modal-emoji">✦</div><h2>Almost yours!</h2><p>You need ${item.price-state.buxns} more Buxns for <b>${escapeHTML(name)}</b>. Play a quick game to earn some.</p><button class="primary-btn" id="playForCoins">Play for Buxns <span>→</span></button>`);$('#playForCoins').onclick=()=>{closeModal();startGame('blitz');};return;}state.buxns-=item.price;state.owned.push(name);save('playroom-owned',state.owned);setBalance();equipItem(item);renderWardrobe();}
  function equipItem(item){state.equipped[item.cat]=item.name;save('playroom-equipped',state.equipped);if(item.cat==='hat'){$('#previewHat').textContent=item.icon;$('#previewHat').style.background=item.color;$('#previewHat').style.boxShadow=`0 4px 0 ${item.color}`;}if(item.cat==='top')$('.preview-body').style.background=item.color;showToast(`${item.name} equipped!`);}
  $$('.wardrobe-tab').forEach(t=>t.addEventListener('click',()=>{$$('.wardrobe-tab').forEach(x=>x.classList.remove('selected'));t.classList.add('selected');state.wardrobeCategory=t.dataset.category;state.wardrobePage=0;renderWardrobe();}));
  $('#nextItems').addEventListener('click',()=>{state.wardrobePage++;renderWardrobe();});$('#prevItems').addEventListener('click',()=>{state.wardrobePage=Math.max(0,state.wardrobePage-1);renderWardrobe();});
  $('#randomizeAvatar').addEventListener('click',()=>{const options=itemCatalog.filter(i=>i.price===0||state.owned.includes(i.name));['hat','top','face'].forEach(cat=>{const arr=options.filter(i=>i.cat===cat),item=arr[Math.floor(Math.random()*arr.length)];if(item)equipItem(item);});showToast('Fresh look!');});
  $('#saveAvatar').addEventListener('click',()=>{save('playroom-equipped',state.equipped);showToast('Look saved!');});
  $('#earnCoinsBtn').addEventListener('click',()=>openModal(`<div class="modal-emoji">✦</div><span class="eyebrow">Buxns make the world go round</span><h2>Earn while you play</h2><p>Finish a mini-game to earn 20–35 Buxns. Grab the shiny Buxns in Buxn Blitz for bonus rewards, then spend them on avatar items.</p><button class="primary-btn" id="playForCoins">Play a game <span>→</span></button>`));document.addEventListener('click',e=>{if(e.target.id==='playForCoins'){closeModal();startGame('blitz');}});
  function setBalance(){save('playroom-buxns',state.buxns);$('#walletBalance').textContent=state.buxns;$('#avatarBalance').textContent=state.buxns;}
  $('#walletBtn').addEventListener('click',()=>{showView('avatar');});$('#profileBtn').addEventListener('click',()=>showView('avatar'));
  function showToast(text){const el=$('#gameToast');el.textContent=text;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),1500);}
  const modes={sprint:{name:'SKY SPRINT',title:'Sky Sprint',goal:'Reach the finish!',reward:25,time:60},blitz:{name:'BUXN BLITZ',title:'Buxn Blitz',goal:'Collect the shiny Buxns!',reward:20,time:45},bounce:{name:'CLOUD BOUNCE',title:'Cloud Bounce',goal:'Bounce to the clouds!',reward:20,time:45},custom:{name:'YOUR WORLD',title:'World Builder',goal:'Reach the green finish!',reward:30,time:60},community:{name:'COMMUNITY WORLD',title:'World Explorer',goal:'Explore this world!',reward:20,time:45}};
  function startGame(which){const mode=modes[which]||modes.sprint;state.game={mode:which,def:mode,x:.12,y:0,vx:0,vy:0,score:0,time:mode.time,done:false,last:performance.now(),platforms:makePlatforms(which)};$('#gameOverlay').classList.add('active');$('#gameResult').classList.remove('show');$('#hudObjective').textContent=mode.goal;$('#hudScore').textContent='0';$('#hudTimer').textContent=mode.time+'s';$('.hud-mode').textContent=mode.name;$('.touch-controls').style.display=which==='blitz'?'none':'';if(which==='custom'&&state.blocks.length===0)showToast('Tap the arrows to hop to the finish!');requestAnimationFrame(gameFrame);}
  function makePlatforms(mode){if(mode==='custom'){return [...state.blocks.map(b=>({x:.18+b.col*.083,y:.72-b.row*.07,w:.08,type:b.type})),{x:.12,y:.82,w:.13,type:'spawn'},{x:.83,y:.28,w:.14,type:'finish'}];}return [{x:.03,y:.80,w:.19,type:'safe'},{x:.26,y:.69,w:.14,type:'safe'},{x:.47,y:.57,w:.16,type:'safe'},{x:.69,y:.45,w:.14,type:'safe'},{x:.85,y:.33,w:.13,type:'finish'}, {x:.17,y:.42,w:.08,type:'coin'},{x:.55,y:.36,w:.08,type:'coin'}];}
  function drawGame(){const g=state.game;if(!g)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);const grad=ctx.createLinearGradient(0,0,0,h);const theme=g.mode==='blitz'?['#ffd081','#f39b98']:g.mode==='bounce'?['#1f3a70','#84b8dc']:['#9bdef0','#927ce2'];grad.addColorStop(0,theme[0]);grad.addColorStop(1,theme[1]);ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);for(let i=0;i<22;i++){let x=(i*173+31)%w,y=(i*97+21)%Math.max(1,h*.64);ctx.fillStyle=`rgba(255,255,255,${.22+(i%3)*.1})`;ctx.beginPath();ctx.arc(x,y,(i%3)+1,0,7);ctx.fill();}
    // atmospheric cloud islands
    for(let i=0;i<6;i++){const x=((i*193-state.camera*.09)%(w+180)+w+180)%(w+180)-60,y=h*(.32+(i%3)*.12);ctx.fillStyle='#ffffff3b';ctx.beginPath();ctx.ellipse(x,y,55,12,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(x-13,y-8,14,0,7);ctx.arc(x+5,y-12,18,0,7);ctx.fill();}
    g.platforms.forEach((p,i)=>{const x=p.x*w-state.camera,y=p.y*h;if(x < -100||x>w+80)return;const pw=Math.max(45,p.w*w),ph=Math.max(10,h*.022);let c=p.type==='finish'?'#65d8a4':p.type==='coin'?'#ffd36b':p.type==='spawn'?'#75c6f2':(blockColors[p.type]||['#a3edb7','#78d797','#58bd78'])[0];ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,pw,ph,7);ctx.fill();ctx.fillStyle='#0000001c';ctx.beginPath();ctx.roundRect(x,y+ph-5,pw,8,4);ctx.fill();if(p.type==='coin'||(g.mode==='blitz'&&i%2===1)){ctx.fillStyle='#fff4ae';ctx.beginPath();ctx.arc(x+pw/2,y-14,9,0,7);ctx.fill();ctx.fillStyle='#ecac36';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText('✦',x+pw/2,y-10);}});
    // player shadow and little block-avatar
    const px=w*.28,py=g.y*h;if(g.mode!=='custom'&&g.y===0){const support=g.platforms.find(p=>p.type==='safe'&&g.x>=p.x&&g.x<=p.x+p.w);py=support?h*support.y-h*.055:h*.68;}ctx.fillStyle='#28325d30';ctx.beginPath();ctx.ellipse(px,py+12,17,5,0,0,7);ctx.fill();ctx.fillStyle='#5e55cc';ctx.beginPath();ctx.roundRect(px-12,py-15,24,24,6);ctx.fill();ctx.fillStyle='#ffd4b1';ctx.beginPath();ctx.roundRect(px-9,py-34,18,19,6);ctx.fill();ctx.fillStyle='#ff8da7';ctx.beginPath();ctx.roundRect(px-11,py-38,22,8,5);ctx.fill();ctx.fillStyle='#403951';ctx.fillRect(px-5,py-27,2,2);ctx.fillRect(px+4,py-27,2,2);
    // finish label
    ctx.fillStyle='#ffffffc7';ctx.textAlign='center';ctx.font='700 11px sans-serif';ctx.fillText(g.def.title, w/2,h-37);
  }
  function gameFrame(now){if(!state.game)return;const g=state.game,dt=Math.min(.04,(now-g.last)/1000);g.last=now;g.time-=dt;if(g.time<=0){finishGame(false);return;}const left=state.keys.has('left')||state.keys.has('ArrowLeft'),right=state.keys.has('right')||state.keys.has('ArrowRight'),up=state.keys.has('up')||state.keys.has('ArrowUp'),down=state.keys.has('down')||state.keys.has('ArrowDown');g.vx=(right?1:0)-(left?1:0);g.x+=g.vx*dt*.55;g.x=Math.max(.04,Math.min(.97,g.x));if(up||state.keys.has('jump')){if(!g.jumping){g.jumping=true;g.vy=-.85;}}if(g.jumping){g.vy+=1.9*dt;g.y+=g.vy*dt;if(g.y>=0){g.y=0;g.vy=0;g.jumping=false;}}
    if(g.mode==='blitz'){g.score+=dt*1.1;if(Math.random()<dt*.55)g.score+=1;}else if(g.mode==='bounce'){g.score+=dt*.55;g.y=Math.sin(now/280)*.025;}
    const target=g.x*canvas.clientWidth-canvas.clientWidth*.28;state.camera+=(target-state.camera)*.07;
    if(g.mode==='custom'){const closeFinish=g.x>.78;if(closeFinish&&(!state.blocks.length||state.blocks.length>=2)){finishGame(true);return;}if(g.x>.78&&state.blocks.length<2&&Math.random()<dt*2)showToast('Place a few more blocks to make your path!');}
    else if(g.x>.9){finishGame(true);return;}
    else if(g.mode==='sprint'&&g.x>.48&&g.x<.51&&g.score<5){g.score+=5;showToast('Nice shortcut! +5');}
    if(g.mode==='blitz'&&Math.random()<dt*.3){g.score+=2;showToast('Buxn collected!');}
