  function finishGame(won){if(!state.game||state.game.done)return;const g=state.game;g.done=true;const reward=won?g.def.reward+Math.min(10,Math.floor(g.score/3)):Math.max(8,Math.floor(g.def.reward*.45));state.buxns+=reward;state.quest=Math.min(10,state.quest+Math.min(10,Math.ceil(reward/4)));save('playroom-quest',state.quest);$('#questProgress').style.width=`${state.quest*10}%`;$('#questText').textContent=`${state.quest} / 10 collected`;if(state.quest>=10&& !load('playroom-quest-paid',false)){state.buxns+=25;save('playroom-quest-paid',true);showToast('Daily quest complete! +25');}setBalance();$('#resultTitle').textContent=won?(g.mode==='custom'?'World conquered!':'You did it!'):'Good try!';$('#resultCopy').textContent=won?`You finished ${g.def.title} and earned ${reward} Buxns.`:`You earned ${reward} Buxns for giving it a go.`;$('#resultReward').textContent=reward;$('#gameResult').classList.add('show');}
