  $('#exitGame').addEventListener('click',stopGame);$('#resultContinue').addEventListener('click',stopGame);$('#resultReplay').addEventListener('click',()=>{const m=state.game?.mode||'sprint';stopGame();startGame(m);});$('#jumpBtn').addEventListener('pointerdown',e=>{e.preventDefault();state.keys.add('jump');});$('#jumpBtn').addEventListener('pointerup',()=>state.keys.delete('jump'));$('#jumpBtn').addEventListener('pointercancel',()=>state.keys.delete('jump'));
  $$('#dpad button').forEach(b=>{const on=e=>{e.preventDefault();state.keys.add(b.dataset.dir);},off=e=>{e.preventDefault();state.keys.delete(b.dataset.dir);};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off);});
  window.addEventListener('keydown',e=>{const map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',' ':'jump'};if(map[e.key]){state.keys.add(map[e.key]);if(state.game)e.preventDefault();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchInput').focus();}});window.addEventListener('keyup',e=>{const map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',' ':'jump'};if(map[e.key])state.keys.delete(map[e.key]);});
  $('#searchInput').addEventListener('input',e=>{const q=e.target.value.toLowerCase();if(!q)return;showView('community');$$('.world-card').forEach(c=>c.style.display=c.textContent.toLowerCase().includes(q)?'':'none');});
  $('#howToBtn').addEventListener('click',()=>openModal(`<div class="modal-emoji">🎮</div><span class="eyebrow">QUICK HOW-TO</span><h2>Jump right in</h2><p>Choose a mini-game and use <b>← →</b> to run and <b>Space / ↑</b> to jump. On phones, use the on-screen arrows and jump button. Collect Buxns, then spend them in your Avatar wardrobe.</p><p>In Build, tap an empty tile to place blocks. Publish your creation to keep it on this device.</p><button class="primary-btn" id="closeGuide">Got it <span>✓</span></button>`));document.addEventListener('click',e=>{if(e.target.id==='closeGuide')closeModal();});
  $('#questProgress').style.width=`${state.quest*10}%`;$('#questText').textContent=`${state.quest} / 10 collected`;setBalance();renderWardrobe();renderCommunity();resizeCanvas();
})();

