const { chromium }=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{const b=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const p=await b.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,hasTouch:true,isMobile:true});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://localhost:3000');await p.waitForTimeout(300);
console.log('mobile widths',await p.evaluate(()=>({viewport:innerWidth,document:document.documentElement.scrollWidth,body:document.body.clientWidth,header:document.querySelector('.topbar').scrollWidth,headerClient:document.querySelector('.topbar').clientWidth,extras:[...document.querySelectorAll('body *')].map(e=>({id:e.id,cls:typeof e.className==='string'?e.className:'',left:Math.round(e.getBoundingClientRect().left),right:Math.round(e.getBoundingClientRect().right)})).filter(e=>e.right>innerWidth||e.left<0).slice(0,8)})));
await p.locator('.game-card[data-game="blitz"]').click();await p.waitForTimeout(250);console.log('blitz launch',await p.locator('.hud-mode').textContent(),'touch display',await p.locator('.touch-controls').evaluate(e=>getComputedStyle(e).display));await p.touchscreen.tap(345,400);await p.waitForTimeout(500);console.log('blitz tap play timer',await p.locator('#hudTimer').textContent(),'score',await p.locator('#hudScore').textContent());await p.locator('#exitGame').click();await p.locator('.game-card[data-game="sprint"]').click();await p.waitForTimeout(200);console.log('sprint controls',await p.locator('.touch-controls').evaluate(e=>getComputedStyle(e).display),await p.locator('#dpad').isVisible(),await p.locator('#jumpBtn').isVisible());const before=await p.locator('#hudTimer').textContent();await p.locator('#dpad button[data-dir="right"]').tap();await p.locator('#jumpBtn').tap();await p.waitForTimeout(350);console.log('touch controls used',before,'=>',await p.locator('#hudTimer').textContent());await p.locator('#exitGame').click();await p.screenshot({path:'/tmp/opencode/playroom-mobile.jpg',type:'jpeg',quality:75,fullPage:false});console.log('page errors',errors);await b.close()})().catch(e=>{console.error(e);process.exit(1)});
