(async()=>{const b=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});const p=await b.newPage({viewport:{width:320,height:740},deviceScaleFactor:1,hasTouch:true,isMobile:true});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://localhost:3000');for(const width of [320,390,768,1024,1280]){await p.setViewportSize({width,height:844});await p.waitForTimeout(100);console.log('viewport',width,'doc width',await p.evaluate(()=>document.documentElement.scrollWidth));}
await p.setViewportSize({width:390,height:844});await p.locator('.game-card[data-game="sprint"]').click();await p.waitForTimeout(200);await p.locator('#dpad button[data-dir="right"]').dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',isPrimary:true});await p.waitForTimeout(1200);await p.locator('#dpad button[data-dir="right"]').dispatchEvent('pointerup',{pointerId:1,pointerType:'touch',isPrimary:true});await p.waitForTimeout(100);console.log('touch gameplay timer',await p.locator('#hudTimer').textContent(),'controls',await p.locator('.touch-controls').evaluate(e=>getComputedStyle(e).display));await p.locator('#exitGame').click();console.log('runtime errors',errors);await b.close()})().catch(e=>{console.error(e);process.exit(1)});
